<template>
  <section class="space-y-5"><div><p class="text-xs font-bold uppercase tracking-wider text-blue-300">Quality and response</p><h1 class="mt-1 text-3xl font-bold text-white">Performance</h1></div><p v-if="error" class="pc-card text-red-300">{{ error }}</p><div v-if="data" class="grid gap-4 md:grid-cols-3"><div v-for="item in metrics" :key="item.label" class="pc-card"><p class="text-xs uppercase tracking-wider text-slate-500">{{ item.label }}</p><p class="mt-3 text-3xl font-bold text-blue-200">{{ item.value }}</p></div></div><div v-if="data" class="pc-card"><h2 class="font-semibold text-white">Pipeline totals</h2><dl class="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><div v-for="item in totals" :key="item.label"><dt class="text-xs uppercase text-slate-500">{{ item.label }}</dt><dd class="mt-1 text-xl font-bold text-white">{{ item.value }}</dd></div></dl></div></section>
</template>
<script setup lang="ts">
definePageMeta({layout:'partner-workspace',middleware:['auth']});const {apiFetch}=useApi();const data=ref<any>();const error=ref('');const display=(v:any,suffix='')=>v===null||v===undefined?'—':`${Number(v).toLocaleString()}${suffix}`;const metrics=computed(()=>data.value?[{label:'Composite score',value:display(data.value.metric.composite_score)},{label:'Average response',value:display(data.value.metric.response_hours_avg,' h')},{label:'Completion rate',value:display(data.value.metric.completion_rate,'%')}]:[]);const totals=computed(()=>data.value?[{label:'All RFQs',value:data.value.counts.total},{label:'Submitted bids',value:data.value.counts.bid_submitted},{label:'Declined',value:data.value.counts.declined},{label:'Completed tasks',value:data.value.tasks.done}]:[]);onMounted(()=>apiFetch<any>('/partner/dashboard').then(x=>data.value=x).catch((e:any)=>error.value=e?.data?.detail||e?.message))
</script>
